import { arrayOf, func, number, shape, string } from 'prop-types'
import styled, { css } from 'styled-components'
import { Button, Nav } from 'grommet'
import Link from 'next/link'
import { SpacedText } from '@zooniverse/react-components'

const StyledUl = styled.ul`
  padding-inline-start: 0;
`

const StyledLi = styled.li`
  list-style-type: none;
  display: flex;
`

const StyledButton = styled(Button)`
  text-decoration: none;
  padding: 5px 20px; // Same as Project About page sidebar
  width: 100%;

  &[aria-current='true'] {
    ${props =>
      props.theme.dark
        ? css`
            background: ${props.theme.global.colors['neutral-1']};
          `
        : css`
            background: ${props.theme.global.colors['accent-1']};
          `}
  }
`

const StyledLink = styled(Link)`
  text-decoration: none;
  padding: 5px 20px; // Same as Project About page sidebar
  width: 100%;

  &[aria-current='page'] {
    ${props =>
      props.theme.dark
        ? css`
            background: ${props.theme.global.colors['neutral-1']};
          `
        : css`
            background: ${props.theme.global.colors['accent-1']};
          `}
  }
`

const DEFAULT_HANDLER = () => {}

function Sidebar({
  activeSection = 0,
  className = '',
  ariaLabel = '',
  sections = [],
  setActiveSection = DEFAULT_HANDLER
}) {
  return (
    <Nav
      aria-label={ariaLabel}
      className={className}
      margin={{ horizontal: 'auto' }}
    >
      <StyledUl>
        {sections.map((section, index) => (
          <StyledLi key={section.name}>
            {section.slug ? (
              <StyledButton
                aria-current={index === activeSection ? 'true' : 'false'}
                href={`#${section.slug}`}
                onClick={() => setActiveSection(index)}
              >
                <SpacedText
                  color={{ light: 'black', dark: 'white' }}
                  weight={index === activeSection ? 'bold' : 'normal'}
                >
                  {section.name}
                </SpacedText>
              </StyledButton>
            ) : (
              <StyledLink
                aria-current={index === activeSection ? 'page' : ''}
                href={section.href || ''}
                onClick={() => setActiveSection(index)}
              >
                <SpacedText
                  color={{ light: 'black', dark: 'white' }}
                  weight={index === activeSection ? 'bold' : 'normal'}
                >
                  {section.name}
                </SpacedText>
              </StyledLink>
            )}

          </StyledLi>
        ))}
      </StyledUl>
    </Nav>
  )
}

export default Sidebar

Sidebar.propTypes = {
  activeSection: number,
  className: string,
  ariaLabel: string,
  sections: arrayOf(
    shape({
      name: string,
      href: string,  // Use either slug OR href. href takes precedence.
      slug: string
    })
  ),
  setActiveSection: func
}
